from __future__ import annotations

from enum import StrEnum
from typing import Self

from pydantic import Field, model_validator

from ai.backend.common.api_handlers import BaseRequestModel
from ai.backend.common.dto.manager.v2.rbac.types import UUIDScope


class AutoGeneratedFileScopeType(StrEnum):
    """The kind of scope an auto-generated file belongs to."""

    DOMAIN = "domain"
    PROJECT = "project"
    USER = "user"


class AutoGeneratedFileOrderField(StrEnum):
    """Fields available for ordering auto-generated files."""

    PATH = "path"
    CREATED_AT = "created_at"


class AutoGeneratedFileScope(BaseRequestModel):
    """Scope for the scoped auto-generated file query; the items are OR'd."""

    domain: list[UUIDScope] | None = Field(
        default=None, description="Domains whose auto-generated files are being read."
    )
    project: list[UUIDScope] | None = Field(
        default=None, description="Projects whose auto-generated files are being read."
    )
    user: list[UUIDScope] | None = Field(
        default=None, description="Users whose auto-generated files are being read."
    )

    @model_validator(mode="after")
    def _require_a_scope(self) -> Self:
        if not self.domain and not self.project and not self.user:
            raise ValueError(
                "AutoGeneratedFileScope requires a non-empty 'domain', 'project' or 'user'"
            )
        return self
